import { apiClient } from "../axiosConfig";
import { buildQueryParams } from "../utils/queryParams";
import type {
  AdminUpdateUserPasswordRequest,
  AdminCreateAdminRequest,
  AdminCreateUserRequest,
  AdminUpdateUserMatchmakingRequest,
  AdminUpdateAdminRequest,
  AdminUpdateUserRequest,
  AdminSupportMessageResponse,
  AdminSupportCategory,
  AdminUserResponse,
  AdminUserPreferencesResponse,
  AdminRole,
  AdminStatus,
} from "../../types/admin";
import type { UserResponse, UserStatus } from "../../types/auth";
import type { TestCountResponse } from "../../types/insights";
import type { UserProfileResponse } from "../../types/profile";
import type { PageResponse, Uuid } from "../../types/shared";

export type AdminUsersParams = {
  email?: string;
  status?: UserStatus;
  onboardingCompleted?: boolean;
  page?: number;
  size?: number;
};

export type AdminAdminsParams = {
  email?: string;
  status?: AdminStatus;
  role?: AdminRole;
  page?: number;
  size?: number;
};

export type AdminSupportMessagesParams = {
  q?: string;
  category?: AdminSupportCategory;
  page?: number;
  size?: number;
};

export const getUsers = async (
  params: AdminUsersParams = {}
): Promise<PageResponse<UserResponse>> => {
  const { data } = await apiClient.get<PageResponse<UserResponse>>(
    "/admin/users",
    { params: buildQueryParams(params) }
  );
  return data;
};

export const getUser = async (userId: Uuid): Promise<UserResponse> => {
  const { data } = await apiClient.get<UserResponse>(`/admin/users/${userId}`);
  return data;
};

export const getUserProfile = async (userId: Uuid): Promise<UserProfileResponse> => {
  const { data } = await apiClient.get<UserProfileResponse>(
    `/admin/users/${userId}/profile`
  );
  return data;
};

export const getUserTestsCount = async (
  userId: Uuid
): Promise<TestCountResponse> => {
  const { data } = await apiClient.get<TestCountResponse>(
    `/admin/users/${userId}/tests/count`
  );
  return data;
};

export const getUserPreferences = async (
  userId: Uuid
): Promise<AdminUserPreferencesResponse> => {
  const { data } = await apiClient.get<AdminUserPreferencesResponse>(
    `/admin/users/${userId}/preferences`
  );
  return data;
};

export const updateUserMatchmakingPreferences = async (
  userId: Uuid,
  payload: AdminUpdateUserMatchmakingRequest
): Promise<AdminUserPreferencesResponse> => {
  const { data } = await apiClient.put<AdminUserPreferencesResponse>(
    `/admin/users/${userId}/preferences/matchmaking`,
    payload
  );
  return data;
};

export const createUser = async (
  payload: AdminCreateUserRequest
): Promise<UserResponse> => {
  const { data } = await apiClient.post<UserResponse>("/admin/users", payload);
  return data;
};

export const updateUser = async (
  userId: Uuid,
  payload: AdminUpdateUserRequest
): Promise<UserResponse> => {
  const { data } = await apiClient.patch<UserResponse>(
    `/admin/users/${userId}`,
    payload
  );
  return data;
};

export const deleteUser = async (userId: Uuid): Promise<void> => {
  await apiClient.delete(`/admin/users/${userId}`);
};

export const updateUserPassword = async (
  userId: Uuid,
  payload: AdminUpdateUserPasswordRequest
): Promise<void> => {
  await apiClient.patch(`/admin/users/${userId}/password`, payload);
};

export const sendUserPasswordResetLink = async (userId: Uuid): Promise<void> => {
  await apiClient.post(`/admin/users/${userId}/password/reset-link`);
};

export const getAdminUsers = async (
  params: AdminAdminsParams = {}
): Promise<PageResponse<AdminUserResponse>> => {
  const { data } = await apiClient.get<PageResponse<AdminUserResponse>>(
    "/admin/admin-users",
    { params: buildQueryParams(params) }
  );
  return data;
};

export const getAdminUser = async (adminId: Uuid): Promise<AdminUserResponse> => {
  const { data } = await apiClient.get<AdminUserResponse>(
    `/admin/admin-users/${adminId}`
  );
  return data;
};

export const createAdmin = async (
  payload: AdminCreateAdminRequest
): Promise<AdminUserResponse> => {
  const { data } = await apiClient.post<AdminUserResponse>(
    "/admin/admin-users",
    payload
  );
  return data;
};

export const updateAdmin = async (
  adminId: Uuid,
  payload: AdminUpdateAdminRequest
): Promise<AdminUserResponse> => {
  const { data } = await apiClient.patch<AdminUserResponse>(
    `/admin/admin-users/${adminId}`,
    payload
  );
  return data;
};

export const deleteAdmin = async (adminId: Uuid): Promise<void> => {
  await apiClient.delete(`/admin/admin-users/${adminId}`);
};

export const getSupportMessages = async (
  params: AdminSupportMessagesParams = {}
): Promise<PageResponse<AdminSupportMessageResponse>> => {
  const { data } = await apiClient.get<PageResponse<AdminSupportMessageResponse>>(
    "/admin/support/messages",
    { params: buildQueryParams(params) }
  );
  return data;
};
